{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Imipramine, a lipophilic tricyclic antidepressant with a dialkylaminopropyl side chain on an aromatic nitrogen, has absolute oral bioavailability of about 47% (range 29-77%) in humans, directly supporting F >= 20% for the query's similar basic diamine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Amitriptyline, another tricyclic antidepressant with a dimethylaminopropylidene chain and two basic centers, shows absolute oral bioavailability of about 43% (range 35-51%) in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fentanyl, an N-phenyl amide with a basic amine and lipophilic aromatic groups, has absolute oral bioavailability of 32% when swallowed as an oral solution, supporting F >= 20% for the query's N-phenyl/indane diamine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Oxybutynin, which shares the diethylamino group and lipophilic aromatic/cyclohexyl system, has low absolute oral bioavailability of about 6% due to extensive first-pass metabolism; this is a contradictory low-F example, but its ester moiety and metabolic soft spots are not present in the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic diamine with an N-phenyl-indan core and a diethylaminopropyl side chain. The most transferable experimental evidence from imipramine, amitriptyline, and fentanyl shows absolute oral bioavailability in the 30-50% range, above the 20% threshold. Low-F analogues such as oxybutynin and rotigotine contain ester or phenol metabolic liabilities absent in the query, making them less transferable. Overall, the evidence supports a high oral bioavailability prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to evidence molecules are moderate (0.24-0.30), limiting quantitative transferability.",
    "No data on the query's metabolic stability, efflux, or first-pass extraction.",
    "The ionization state and permeability of the query in vivo are uncertain despite physicochemical priors."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

